import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-continuity-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==72 and rep['all_bytes_equal'] and rep['matched_files']==121 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('CT_INFO','CT_COUNT','CT_EFF','CT_PRICE','CT_INV','CT_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='CT_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('CT_COUNT','CT_EFF','CT_PRICE','CT_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['nonpositive_path_beta_weeks'] if x['nonpositive_path_beta_weeks'] is not None else '해당 없음'])
 evidence={'build':'1003i1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only repeated-history development; positive signed price-continuity interaction beyond r7/r28 and signed-day counts. Only fixed price paths, not actual attention/news, investor survey or original 12-month cross-sectional replication. No accepted strategy, unused OOS, other-asset trading or control promotion','references':['https://doi.org/10.1016/j.frl.2023.104069','https://doi.org/10.1016/j.frl.2023.104109','https://doi.org/10.1016/j.heliyon.2023.e14236','https://rpc.cfainstitute.org/research/cfa-digest/2015/03/frog-in-the-pan-continuous-information-and-momentum-digest-summary']}
 (DOWN/'btc-continuity-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-continuity-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-continuity-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_continuity_study.py','test_btc_continuity_study.py','verify_btc_continuity_study.py','reproduce_btc_continuity_study.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  files.extend([(ROOT/'data/btc-venue-20261003/masks.json','input-receipts/btc-no-trade-mask.json'),(DOC/'EXPERIMENT_BTC_CONTINUITY_20261003.md','source/EXPERIMENT_BTC_CONTINUITY_20261003.md')])
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),SOURCE_NOTE)
 html=HTML
 proof_text=f"20합성검사,329BTC ZIP·{v['raw_valid_spot_boundary_closes']:,}개 유효 일경계종가·{v['raw_feature_weeks']:,}주피처·{v['independent_model_fits']:,}정규방정식 모형·{v['raw_daily_decisions']:,}일판단·{v['independent_target_quantities']:,}폐형식 수량·{v['no_trade_decisions']:,}무거래·{v['raw_mark_funding_events']:,}펀딩·{v['events']:,}이벤트·{v['daily_equities']:,}일말을 확인했습니다. 시간DD·담보·연도·노출·선정·추세항등·180불확실성 구간 포함. 최대 계좌차{v['max_numeric_error']:.3g}USDT,모형차{v['max_fit_numeric_error']:.3g}. 소켓 차단121파일 바이트 일치. 검산 성공은 전략 성공이 아닙니다."
 html=html.replace('{{PROOF}}',proof_text)
 for token,value in [('BASE',table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')),('FORECAST',table(['기간','추가지연(일)','모형','공통주','MSE','방향정확도%','추가항계수≤0주'],forecast,'forecast-results')),('ANNUAL',table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')),('COST',table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')),('CI',table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')),('MATRIX',table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts'))]:html=html.replace('{{'+token+'}}',value)
 assert '{{' not in html
 (DOC/'btc-continuity-research.html').write_text(html);p=DOC/'btc-web-research.html';old=p.read_text()
 if 'id="continuity-followup"' not in old:p.write_text(old.replace('<h1>','<p id="continuity-followup" class="boundary">추가72계좌: <a href="btc-continuity-research.html">가격 변화 연속성 검증 ↗</a></p><h1>',1))
 files=['btc-continuity-research.html','btc-web-research.html','downloads/btc-continuity-evidence.zip','downloads/btc-continuity-evidence.json','downloads/btc-continuity-summary.csv','EXPERIMENT_BTC_CONTINUITY_20261003.md','BTC_WEB_RESEARCH_20261002.md'];out=ROOT/'runs/btc-continuity-report-20261003';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files),'zip_bytes':(DOWN/'btc-continuity-evidence.zip').stat().st_size}))
SOURCE_NOTE="""BTC-only signed price-continuity interaction study.
No new provider data were collected. Only existing BTC spot completed hourly boundary closes form the29daily prices/28daily log returns, sign counts including zero days, signed continuity interaction and magnitude-efficiency comparator.
Shared market: data/search-1458/market.json.gz canonical SHA9909be60d1d4db6b47f766de26894de9cbb55222530f9c3bbdbc19ef0899faa4, gzip7e596342c65607453bbc86eb8c632e98eee514c06c53bec8876cefb3fd38d1a8. Raw329publicBTC ZIPs/checksums and data/btc-venue-20261003/masks.json SHAbfefb3a32526cfcdf2a5b8151cbfe87f0a749986bbf4cb7d31d7c0d65cf2dfcd remain unchanged.
Economic source scope: CFA Institute2015 Digest of Frog in the Pan https://rpc.cfainstitute.org/research/cfa-digest/2015/03/frog-in-the-pan-continuous-information-and-momentum-digest-summary is a secondary summary, NOT an obtained original paper or BTC evidence. Only its behavioral hypothesis/formula informed our own fixed4weekBTCtime-series question. No other-asset datasets/trades. Petkova2023 Extrapolative beliefs about Bitcoin returns, DOI10.1016/j.frl.2023.104069, and Meng/Goodell/Shen2023 Information shocks and investor underreaction: Evidence from the Bitcoin market, DOI10.1016/j.frl.2023.104109, were available as publisher-provided RePEc abstracts only, not full text. They motivate caution; price counts do not measure the Sentix survey, investor attention or identified information shocks. Opposing large-jump underreaction findings are retained.
All72hypothetical accounts, price-path-derived features/forecasts/plans/independent proof and socket replay, source/test/verifier/reproducer/specification/no-trade mask are included. Original publication texts/PDFs are not mirrored. Reproduction still needs the exact shared BTC market/ZIP/funding/mark files and baseline E_SPOT accounts, repository paths plus shared Python modules/dependencies separately. This ZIP is NOT a standalone environment.
Zero or incomplete28daypaths are not filled, clipped, repaired from other series or epsilon-adjusted. Additional7daydata lag applies to all features and training inputs, not future labels. Original net-return/drawdown/volatility/annual/forecast gates are unchanged. Repeated development paths are not unused OOS; no accepted live strategy, private accounts, other assets or external services.
"""
HTML='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 가격 연속성 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003i1</p><h1>가격 변화의 연속성도<br>BTC 전략 기준을 넘지 못했습니다.</h1><p class="lead">같은 누적수익이라도 상승·하락일의 구성이 추가 정보를 주는지 검정했습니다. 최근 예측오차는 소폭 개선했지만 주기간 수익·위험·연도 일관성·지연 내구성은 기준에 미달했습니다.</p><div class="facts"><article><b>72</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>CT_INFO 기본 후보</span></article><article><b>121</b><span>파일 소켓차단 바이트 일치</span></article></div><p class="boundary">2022–2025와2026.01–08은 이미 본 개발 자료입니다. 새 OOS·원문전략 복제·인과 입증이 아닙니다. BTC만 가상 거래하며 실제 주의·뉴스·설문 응답을 관측한 것은 아닙니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT,수익·최대낙폭(DD)은 %. TREND는 저장된 E_SPOT와 일별·주요회계가 같습니다.</p>{{BASE}}<p>기본 주 +48.80%·DD13.56%·연변동성13.58%·Sharpe0.7985,최근 +0.89%·DD1.68%. 주 수익52.838713%·변동성13.343621%·Sharpe0.8과 최근 수익4.628391% 기준을 유지했습니다. 2022년 −4.21%·2025년 −4.66%로 양수 연도는2개입니다.</p><p>주 DD는 TREND와 실제 같은13.5619520261%지만 고정 기준13.561952%를 약0.0000000261%p 초과해 엄격 관문은 false로 보존했습니다. 이 반올림 경계와 무관하게 수익·변동성·연도·지연·추가정보 조건도 실패했습니다.</p><p>최근 INFO는 새 발동0일이라 기존 추세 대조와 같습니다. 부분적인 예측오차 개선이나 대조 EFF의 주 수익을 근거로 후보를 바꾸지 않았습니다.</p></section><section><h2>관측한 것은 정보가 아니라 가격경로입니다</h2><p>공개 CFA 학술요약은 작은 동부호 정보가 최소주의 문턱에 못 미쳐 늦게 반영될 수 있다는 행동기전을 설명합니다. 원논문 전문이나 BTC 검증이 아니라2차요약이며,원12개월·여러 종목 연구를 BTC4주 시계열로 복제했다고 주장하지 않습니다.</p><p>BTC 기대 형성 연구의 실제 입력은 Sentix 설문이고,초록은 단기 설명력이 작다고 보고합니다. 다른 BTC 정보충격 연구는 큰 점프에도 과소반응이 있으며 주의가 많으면 약해진다고 합니다. 두 전문은 확보하지 못했으며,가격일수로 설문·주의·정보충격을 식별했다고 하지 않습니다.</p><p>다른 캔들 경계 논문은 수수료0에 이르는 고빈도 거래량 경로를 사용하고,원문에서도 초기1,000달러는 전액 손실입니다. 그 비용 가정이나1분 전략을 이번 연구에 가져오지 않았습니다. 과거24h곡선 전략·세미분산 창도 재조정하지 않았습니다.</p></section><section><h2>누적수익과 일수 구성의 상호작용</h2><p>28일 일수익에서 q=(양수일−음수일)/28. 0수익일도 분모에 포함합니다. r28은28일 누적 로그수익,연속성 c=sign(r28)×q,정보이산도 ID=−c,추가항 z=r28×c=abs(r28)×q입니다. r28×abs(q)와는 다릅니다.</p><p>예를 들어 누적수익이 같은 상승 경로라도 작은 상승이 꾸준한 경우와 많은 작은 하락을 한 번의 큰 상승이 뒤집은 경우를 구별합니다. 별도 EFF는 e=r28×abs(r28)/sum(abs(일수익))를 써서 변화 횟수와 크기 기반 효율을 분리합니다.</p><p>INFO=가격7/28일+q+z,COUNT=가격+q,EFF=가격+e,PRICE=가격2. 네 모형 모두 같은 유효행·104달력주·최소52주·최근1주 분리·달력1주 HAC입니다. INFO는 z계수&gt;0·비용+SE·COUNT 대비 같은 방향 추가분 모두 필요합니다. COUNT/EFF는 자기 추가계수&gt;0·자기 비용+SE만 요구합니다.</p><p>주8주56일 발동은 모두 롱,최근 발동0일. 주208공통주 중137주·최근34주 중24주에서 INFO 추가계수≤0였고,무제약 학습 결과를 뒤집지 않았습니다. 계수 양수만으로 실제 매매가 발동하는 것도 아닙니다.</p><p>주 MSE INFO0.005293181804 vs COUNT0.005116528007·PRICE0.004896190546으로 악화. 최근은 INFO0.004259388337 vs COUNT0.004264143756·PRICE0.004307522722로 소폭 개선했습니다. 두 기간 동시 개선 및 순익 기준을 충족한 것은 아닙니다.</p><p>INFO 비용2배 +42.64% / +0.65%,추가1h +47.75% / +0.65%,추가24h +29.62% / −1.35%,자료7일 추가지연 +13.88% / −5.07%,위험10% +22.27% / +0.53%. 모든 조건과 기각을 보존합니다.</p><details><summary>예측과 추가항 부호</summary>{{FORECAST}}</details><details><summary>연도별 수익</summary>{{ANNUAL}}</details><details><summary>롱숏·비용·펀딩·위험</summary>{{COST}}</details><details><summary>모든 대조군 차이의 불확실성</summary><p>14일 원형블록2,000회95%구간(%/일);7/28일은 JSON. 반복개발의 선택 문제를 제거하는 독립 입증이 아닙니다.</p>{{CI}}</details></section><section><h2>완료 가격·비용·지연 경계</h2><p>새 수집 없이 동결된 BTC 가격만 재사용했습니다. 월요일 T까지 완료된29개 UTC 일경계종가가 모두 필요합니다. 무거래·잘못된 종료시각·누락은 무효이고,전체0인 경로에는 epsilon이나 다른 창을 넣지 않습니다. 온체인 결측이나 일중분산 품질마스크를 이 가격경로에 덧씌우지도 않습니다.</p><p>기본source+1h 시가·추가1h/24h 집행지연,추가7일 피처지연을 분리했습니다. 현물10bp/선물5bp+편도1.5bp 불리한 impact,실제 funding,수량/금액 최소치·5%p조절밴드·종료비용 포함. 위험20%/총명목상한1배. 실제호가·부분체결·과거규정·순간청산·세금·운영비는 미복원입니다.</p><details id="matrix"><summary>72계좌 전체 보기</summary>{{MATRIX}}</details></section><section id="proof"><h2>독립 검산·차단 재현</h2><p>{{PROOF}}</p><p>사전b19802c →20검사구현8cb38f2 → 독립4003ab3. 독립 검산은 원시BTC ZIP에서 가격경로를 다시 만들고,별도 정규방정식·HAC·폐형식 수량과 Decimal 원장을 사용했습니다. 이전 계좌 전체를 다시 계산하거나 원자료를 변경하지 않았습니다.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-continuity-evidence.zip">72계좌·피처·검산 ZIP ↓</a><a download href="downloads/btc-continuity-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-continuity-summary.csv">72조건 CSV ↓</a></div><p><a href="EXPERIMENT_BTC_CONTINUITY_20261003.md">성과 전 명세·고정 입력</a> · <a href="BTC_WEB_RESEARCH_20261002.md">원문 감사·실패 기록</a> · <a href="https://rpc.cfainstitute.org/research/cfa-digest/2015/03/frog-in-the-pan-continuous-information-and-momentum-digest-summary">CFA 공개2차요약</a> · <a href="https://doi.org/10.1016/j.frl.2023.104109">BTC 정보충격 논문</a></p><p>ZIP에는 사용한 가격경로·피처·전 계좌·검산·코드·명세를 제공합니다. 공통 BTC 시장자료·329원시ZIP·기존추세 결과·공유모듈·경로·의존성은 별도 필요하며 완전 독립 실행환경이 아닙니다. 논문 PDF나 원설문 자료는 포함하지 않습니다.</p><p>아직 만족할 전략은 없습니다. 실거래·상시모의 서비스 없이 공개 연구만 수행합니다.</p></section><footer>BUILD1003i1 · BTC-only · 실거래 없음</footer></main></body></html>'''
